import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"Panel rápido (Configuración)","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Mecanismo central e interruptor general","slug":"_1-mecanismo-central-e-interruptor-general","link":"#_1-mecanismo-central-e-interruptor-general","children":[]},{"level":2,"title":"2. Espacios de trabajo (Workspaces)","slug":"_2-espacios-de-trabajo-workspaces","link":"#_2-espacios-de-trabajo-workspaces","children":[]},{"level":2,"title":"3. Configuración de orígenes (Sources)","slug":"_3-configuracion-de-origenes-sources","link":"#_3-configuracion-de-origenes-sources","children":[]},{"level":2,"title":"4. Pestañas de plugins (Plugin Tabs)","slug":"_4-pestanas-de-plugins-plugin-tabs","link":"#_4-pestanas-de-plugins-plugin-tabs","children":[]},{"level":2,"title":"5. Vinculación con aplicaciones y lista negra","slug":"_5-vinculacion-con-aplicaciones-y-lista-negra","link":"#_5-vinculacion-con-aplicaciones-y-lista-negra","children":[]},{"level":2,"title":"6. Guía de uso e interacción","slug":"_6-guia-de-uso-e-interaccion","link":"#_6-guia-de-uso-e-interaccion","children":[]}],"relativePath":"es-ES/user-guide/settings/quick-panel.md","filePath":"es-ES/user-guide/settings/quick-panel.md","lastUpdated":1791112464000}`),a={name:`es-ES/user-guide/settings/quick-panel.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="panel-rapido-configuracion" tabindex="-1">Panel rápido (Configuración) <a class="header-anchor" href="#panel-rapido-configuracion" aria-label="Permalink to “Panel rápido (Configuración)”">​</a></h1><p>El <strong>Panel rápido (Quick Panel)</strong> es un espacio de trabajo flotante diseñado para la consulta rápida de archivos, la gestión del contexto de proyectos y el depósito de archivos mediante arrastrar y soltar. Al invocarse, se acopla automáticamente a la esquina inferior derecha de la ventana activa, permitiéndote acceder y preparar archivos sin cambiar de contexto.</p><h2 id="_1-mecanismo-central-e-interruptor-general" tabindex="-1">1. Mecanismo central e interruptor general <a class="header-anchor" href="#_1-mecanismo-central-e-interruptor-general" aria-label="Permalink to “1. Mecanismo central e interruptor general”">​</a></h2><ul><li><strong>Habilitar Panel rápido</strong>: Interruptor maestro; cuando está desactivado, el atajo deja de interceptar pulsaciones.</li><li><strong>Atajo de invocación</strong>: Por defecto <strong><code>Ctrl+F2</code></strong> (personalizable en <a href="./hotkeys-page.html"><strong>Configuración → Atajos de teclado</strong></a>).</li><li><strong>Acoplamiento inteligente y dimensiones</strong>: Se ajusta por defecto a la mitad del ancho y alto de la ventana anfitriona (con un tamaño mínimo de <code>280 × 200px</code> para asegurar la legibilidad). Si una ventana de Lertaro ya tiene el foco, la invocación se ignora para no apilar ventanas; si el panel ya está abierto, el mismo atajo lo cierra.</li></ul><h2 id="_2-espacios-de-trabajo-workspaces" tabindex="-1">2. Espacios de trabajo (Workspaces) <a class="header-anchor" href="#_2-espacios-de-trabajo-workspaces" aria-label="Permalink to “2. Espacios de trabajo (Workspaces)”">​</a></h2><p>Permiten organizar carpetas por proyecto o tarea:</p><ul><li><strong>Gestión de espacios de trabajo</strong>: La lista izquierda permite <strong>Crear</strong>, <strong>Duplicar</strong> y <strong>Eliminar</strong>, con ordenación por arrastre que se refleja en la barra de pestañas.</li><li><strong>Propiedades</strong>: <ul><li><strong>Nombre</strong>: Texto de la pestaña (usa el nombre predeterminado localizado si se deja en blanco).</li><li><strong>Interruptor de activación</strong>: Controla la presencia de la pestaña en la barra. Pulsar <strong>×</strong> en una pestaña del panel la oculta; se puede volver a activar aquí.</li></ul></li></ul><p>Los espacios de trabajo seleccionados se configuran en dos pestañas: <strong>Orígenes</strong> y <strong>Aplicaciones</strong>.</p><h2 id="_3-configuracion-de-origenes-sources" tabindex="-1">3. Configuración de orígenes (Sources) <a class="header-anchor" href="#_3-configuracion-de-origenes-sources" aria-label="Permalink to “3. Configuración de orígenes (Sources)”">​</a></h2><p>Cada origen representa un grupo independiente dentro del espacio de trabajo:</p><ul><li><strong>Añadir carpeta</strong>: Selecciona el directorio en disco.</li><li><strong>Modo de visualización</strong>: <ul><li><strong>Archivos modificados recientemente</strong> —— Consulta el índice en memoria en submilisegundos para mostrar cambios recientes (los más nuevos primero).</li><li><strong>Todo el contenido</strong> —— Muestra todos los archivos, opcionalmente ordenados por fecha de modificación descendente o por nombre (útil como barra fija de accesos directos).</li><li><strong>Solo carpetas</strong> —— Lista únicamente directorios.</li><li><strong>Solo archivos</strong> —— Lista únicamente archivos.</li></ul></li><li><strong>Incluir subcarpetas</strong>: Incluye archivos descendientes de forma recursiva.</li><li><strong>Aceptar archivos arrastrados</strong>: Permite arrastrar archivos, carpetas o imágenes web desde otras ventanas. Lertaro ejecuta una copia nativa de Windows con avisos de conflicto y opción de deshacer.</li><li><strong>Reglas de filtrado</strong>: Filtra las extensiones visibles mediante comodines o filtros <code>@</code> de la sintaxis de búsqueda (p. ej. <code>*.mp4;*.mkv</code>, <code>*.lnk;:@doc;:@img</code> o <code>*.lnk;:@doc|img</code>).</li><li><strong>Límite de elementos y tiempo</strong>: Restringe la cantidad máxima visible (0 para ilimitado) o muestra solo archivos modificados en los últimos N minutos.</li><li><strong>Lista detallada frente a mosaico de miniaturas</strong>: Escoge entre vista de lista compacta o cuadrícula de miniaturas (las miniaturas escalan proporcionalmente conservando su formato original).</li></ul><h2 id="_4-pestanas-de-plugins-plugin-tabs" tabindex="-1">4. Pestañas de plugins (Plugin Tabs) <a class="header-anchor" href="#_4-pestanas-de-plugins-plugin-tabs" aria-label="Permalink to “4. Pestañas de plugins (Plugin Tabs)”">​</a></h2><p>Los plugins pueden registrar listas dinámicas globales en el Panel rápido. El plugin CoreExtensions incluye cinco pestañas predefinidas:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Pestaña de plugin</th><th style="text-align:left;">Contenido</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Favoritos</strong></td><td style="text-align:left;">Elementos destacados con estrella; las URLs se abren en el navegador predeterminado.</td></tr><tr><td style="text-align:left;"><strong>Historial</strong></td><td style="text-align:left;">Elementos y aplicaciones ejecutados recientemente mediante Lertaro.</td></tr><tr><td style="text-align:left;"><strong>Historial de Windows</strong></td><td style="text-align:left;">Resuelve los Documentos recientes de Windows en rutas físicas reales.</td></tr><tr><td style="text-align:left;"><strong>Última carpeta</strong></td><td style="text-align:left;">Rastrea la carpeta recién visitada en el Explorador o en cuadros de diálogo.</td></tr><tr><td style="text-align:left;"><strong>Archivos recientes</strong></td><td style="text-align:left;">Agrupa los archivos más nuevos de todas las carpetas configuradas usando el índice.</td></tr></tbody></table><p>Cada pestaña de plugin se puede activar/desactivar y configurar en modo Lista o Mosaico.</p><h2 id="_5-vinculacion-con-aplicaciones-y-lista-negra" tabindex="-1">5. Vinculación con aplicaciones y lista negra <a class="header-anchor" href="#_5-vinculacion-con-aplicaciones-y-lista-negra" aria-label="Permalink to “5. Vinculación con aplicaciones y lista negra”">​</a></h2><ul><li><strong>Aplicaciones</strong>: Asocia nombres de procesos (p. ej. <code>chrome.exe</code> o <code>devenv.exe</code>) al espacio de trabajo. Al invocar el panel sobre estas aplicaciones, se abrirá directamente el espacio de trabajo correspondiente.</li><li><strong>Lista negra exclusiva del Panel rápido</strong>: Lista de procesos sobre los que no debe aparecer el panel. Se <strong>suma</strong> a la lista negra global de atajos.</li></ul><h2 id="_6-guia-de-uso-e-interaccion" tabindex="-1">6. Guía de uso e interacción <a class="header-anchor" href="#_6-guia-de-uso-e-interaccion" aria-label="Permalink to “6. Guía de uso e interacción”">​</a></h2><ul><li><strong>Filtrado difuso en vivo</strong>: La barra de búsqueda superior derecha admite coincidencia difusa fzf y alias de pinyin para filtrar el espacio de trabajo activo. Filtra <strong>solo nombres</strong> y nunca reordena una lista; un grupo cuyos elementos desaparecen todos se oculta, mientras su pestaña permanece. <code>Escape</code> borra primero el filtro y solo un <strong>segundo</strong> <code>Escape</code> cierra el panel.</li><li><strong>Navegación por teclado</strong>: Las flechas de dirección navegan entre grupos; pulsa <code>Enter</code> para abrir el elemento resaltado y el panel sigue abierto. La secuencia <strong>no</strong> da la vuelta: el primer y el último elemento visibles son extremos definitivos, los grupos vacíos se saltan, y sin nada seleccionado todavía tanto <code>↑</code> como <code>↓</code> caen en el primer elemento. En la vista de mosaico las cuatro flechas se mueven por la cuadrícula visual: <code>←</code>/<code>→</code> siguen el orden de lectura y atraviesan los límites de las filas, <code>↑</code>/<code>↓</code> conservan la columna.</li><li><strong>Cambio de pestañas</strong>: Pulsa <code>Ctrl</code> + <code>1</code>–<code>9</code> para alternar rápidamente entre pestañas de espacios de trabajo y plugins.</li><li><strong>QuickLook y fijación</strong>: Pulsa <code>Alt+P</code> para abrir la vista previa acoplada; pulsa <code>Ctrl+T</code> (o el botón de fijación del encabezado) para fijar el panel y evitar que se cierre al perder el foco.</li><li><strong>Dónde recae el foco</strong>: Al invocar el panel el cursor queda en el cuadro de filtro con la primera entrada ya seleccionada, así que escribir reduce la lista de inmediato. Mientras ese cuadro tiene el foco, los atajos de acciones de los plugins se apartan a propósito; <code>Ctrl+A</code> y <code>Ctrl+C</code> significan edición de texto aquí, no operaciones de archivos.</li><li><strong>Panel de acciones flotante</strong>: La <strong>soltura</strong> del clic derecho (no su pulsación) abre el mismo panel de acciones flotante que muestra la Ventana principal, anclado al cursor, por lo que un clic derecho en una fila no seleccionada actúa sobre esa fila. El panel pasa entonces a hacerse con <code>↑ ↓ ← →</code>, <code>Enter</code>, <code>Space</code> y <code>Escape</code>. Como cuelga su gestor de teclas del propio panel, se ignora el clic fuera que, de otro modo, cerraría el panel mientras esté abierto.</li><li><strong>El ratón sobre las filas</strong>: El doble clic izquierdo abre; un doble clic <strong>derecho</strong> solo vuelve a abrir el panel y nunca inicia nada. El clic central alterna la vista previa. Pasar el ratón por encima de una fila mueve la selección.</li><li><strong>Mover el panel</strong>: Aparece una barra de arrastre en el encabezado cuando el puntero se acerca; arrastrar ahí mueve el panel, y el panel sobrevive al arrastre (por eso un archivo arrastrado desde el Explorador puede acabar dentro).</li><li><strong>Clic fuera</strong>: El panel se oculta unos 200 ms después de que el foco se vaya, y no actúa cuando lo estabas arrastrando, cuando está fijado, mientras el panel de acciones flotante esté abierto y mientras la vista previa que abrió tenga el primer plano; hacer clic en tu propia vista previa no es un clic fuera.</li><li><strong>Edición de la selección</strong>: Hacer clic en el espacio en blanco dentro de un grupo limpia la selección de <strong>todos</strong> los grupos a la vez (salvo que se mantenga <code>Ctrl</code> o <code>Shift</code>). Un arrastre rectangular selecciona dentro de su propio grupo, y con <code>Ctrl</code> de forma acumulativa; un rectángulo que empieza en un grupo no alcanza a otro.</li><li><strong>Soltar archivos dentro</strong>: Un arrastre que <strong>empezó dentro de Lertaro</strong> nunca se acepta, así que un arrastre a medio terminar no puede convertirse en una copia indeseada. Como el panel se cierra al hacer clic fuera, arrastrar un archivo desde el Explorador solo funciona con el panel <strong>fijado</strong>. Soltar archivos siempre produce una copia, nunca un movimiento.</li><li><strong>Encabezados de grupo</strong>: Hacer clic en el nombre, la ruta o la línea de reglas del encabezado pliega y despliega el grupo; Ordenar y Vista son botones separados a su lado. La ordenación, el modo de vista y el estado de plegado son de la sesión, mientras que el orden de las pestañas y el cierre de una pestaña se guardan.</li></ul>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};